pub fn replace_source(
    &self,
    source: &str,
    kind: &str,
    sha256: &str,
    chunks: &[NewChunk],
) -> Result<Vec<i64>> {
    let tx = self
        .conn
        .unchecked_transaction()
        .map_err(db("starting a source replace"))?;
    tx.execute("DELETE FROM chunks WHERE source = ?1", params![source])
        .map_err(db("removing a source's old chunks"))?;
    let mut ids = Vec::with_capacity(chunks.len());
    for c in chunks {
        tx.execute(
            "INSERT INTO chunks(source, kind, title, ordinal, body, sha256, created_at)
             VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7)",
            params![source, kind, c.title, c.ordinal, c.body, sha256, now_unix()],
        )
        .map_err(db("inserting a chunk"))?;
        ids.push(tx.last_insert_rowid());
    }
    tx.commit().map_err(db("committing a source replace"))?;
    Ok(ids)
}

def combine(verdicts: dict[str, dict[str, dict]], pair_ids: list[str], old_dropped: set) -> dict:
    """verdicts: judge -> pair_id -> parsed outcome. The kept ids (both judges keep), each judge's
    outcome counts, the 2x2 agreement table, and the comparison with the first check."""
    a, b = list(verdicts)
    table = {"both_keep": 0, f"only_{a}": 0, f"only_{b}": 0, "neither": 0}
    counts = {j: {} for j in verdicts}
    kept = []
    not_asked = {"outcome": "not asked (the other judge dropped it)"}
    for pid in pair_ids:
        va, vb = verdicts[a].get(pid, not_asked), verdicts[b].get(pid, not_asked)
        ka, kb = keeps(va), keeps(vb)
        for j, v in ((a, va), (b, vb)):
            o = v["outcome"]
            counts[j][o] = counts[j].get(o, 0) + 1
        key = "both_keep" if ka and kb else f"only_{a}" if ka else f"only_{b}" if kb else "neither"
        table[key] += 1
        if ka and kb:
            kept.append(pid)
    kept_set = set(kept)
    old_kept = set(pair_ids) - old_dropped
    return {
        "pairs": len(pair_ids),
        "kept": len(kept),
        "kept_ids": kept,
        "dropped_ids": [p for p in pair_ids if p not in kept_set],
        "judges_disagree": table[f"only_{a}"] + table[f"only_{b}"],
        "agreement": table,
        "outcomes": counts,
        "against_first_check": {
            "kept_by_both_checks": len(kept_set & old_kept),
            "kept_now_dropped_before": len(kept_set - old_kept),
            "dropped_now_kept_before": len(old_kept - kept_set),
            "dropped_by_both": len(set(pair_ids) - kept_set - old_kept),
        },
    }

/// The evidence the verifier is shown, in order: supplied context first, then the
/// retrieved passages placed strongest-first and second-strongest-last.
pub fn evidence_list(claim: &Claim, retrieved: &[Passage]) -> Vec<Passage> {
    let mut out: Vec<Passage> = claim
        .context
        .iter()
        .enumerate()
        .map(|(i, e)| Passage {
            id: format!("ctx{}", i + 1),
            source: e.source.clone(),
            text: e.text.clone(),
        })
        .collect();
    out.extend(lost_in_the_middle(retrieved.to_vec()));
    out
}

