pub fn parse(s: &str) -> Option<Self> {
    let norm: String = s
        .trim()
        .to_lowercase()
        .chars()
        .map(|c| if c == ' ' || c == '-' { '_' } else { c })
        .collect();
    match norm.as_str() {
        "supported" => Some(VerdictKind::Supported),
        "unsupported" => Some(VerdictKind::Unsupported),
        "cannot_tell" => Some(VerdictKind::CannotTell),
        _ => None,
    }
}

