/// A reason a file is not indexed, if it is not: secrets-like names.
pub fn secret_like(name: &str) -> bool {
    let n = name.to_ascii_lowercase();
    n.starts_with(".env")
        || n.starts_with("id_")
        || n.contains("credentials")
        || [".pem", ".key", ".p12", ".pfx"]
            .iter()
            .any(|e| n.ends_with(e))
}

